// File: internal/proxy/util.go, lines 144-162
func translateOutputFields(outputFields []string, schema *schemaInfo, removePkField bool) ([]string, []string, []string, bool, error) {
    ...
    for _, outputFieldName := range outputFields {
        outputFieldName = strings.TrimSpace(outputFieldName)
        if outputFieldName == primaryFieldName {
            userRequestedPkFieldExplicitly = true
        }
        if outputFieldName == "*" {
            userRequestedPkFieldExplicitly = true
            for fieldName, field := range allFieldNameMap {
                if schema.CanRetrieveRawFieldData(field) {
                    resultFieldNameMap[fieldName] = true
                    userOutputFieldsMap[fieldName] = true
                }
            }
            useAllDyncamicFields = true
        }
    }
    ...
}

// The wildcard '*' is correctly handled by iterating through all fields in the schema
// and adding only those fields that CanRetrieveRawFieldData() returns true for.
// In the test case, the schema only contains 2 fields (id, vector), so both are returned.
